package com.sathavahana.kalamkari.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="addresses") public class Address { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="recipient_name") private String recipientName; private String line1,line2,city,state; @Column(name="postal_code") private String postalCode; private String country="India",phone; @Column(name="created_at") private Instant createdAt=Instant.now(); public Address(){} public Long getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getRecipientName(){return recipientName;} public void setRecipientName(String v){recipientName=v;} public String getLine1(){return line1;} public void setLine1(String v){line1=v;} public String getLine2(){return line2;} public void setLine2(String v){line2=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public String getState(){return state;} public void setState(String v){state=v;} public String getPostalCode(){return postalCode;} public void setPostalCode(String v){postalCode=v;} public String getCountry(){return country;} public void setCountry(String v){country=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} }
